table.sql:
CREATE TABLE support_knowledge_docs ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), category_id UUID REFERENCES ticket_categories(id),
-- Conteúdo do documento (gerado por IA) title TEXT NOT NULL, problem_description TEXT NOT NULL, -- descrição canônica do problema problem_variants TEXT[] DEFAULT '{}', -- variações de como o problema apareceu solution_steps JSONB NOT NULL, -- array de passos [{step: int, text: str, code?: str}] solution_summary TEXT NOT NULL, -- resposta curta em linguagem natural (para a IA usar) tags TEXT[] DEFAULT '{}', keywords TEXT[] DEFAULT '{}',
-- Origem e qualidade source_ticket_ids UUID[] DEFAULT '{}', -- tickets que geraram este documento resolution_count INTEGER NOT NULL DEFAULT 1, -- quantas vezes foi usado com sucesso avg_csat NUMERIC(3,2) DEFAULT NULL, -- CSAT médio das resoluções via este doc confidence_score NUMERIC(4,3) DEFAULT 0.700, -- confiança acumulada (cresce com uso)
-- Estado de publicação status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'active', 'archived', 'needs_review')), auto_published BOOLEAN NOT NULL DEFAULT FALSE, -- TRUE se publicado automaticamente (CSAT ≥ 4.0) reviewed_by UUID REFERENCES auth.users(id), reviewed_at TIMESTAMPTZ,
-- Metadados created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW() );
CREATE INDEX idx_kb_docs_category ON support_knowledge_docs(category_id) WHERE status = 'active'; CREATE INDEX idx_kb_docs_status ON support_knowledge_docs(status);

CREATE TABLE ticket_ai_interactions ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), ticket_id UUID NOT NULL REFERENCES support_tickets(id) ON DELETE CASCADE, interaction_type TEXT NOT NULL CHECK (interaction_type IN ( 'triage', 'knowledge_search', 'autonomous_response', 'draft_suggestion', 'satisfaction_check', 'auto_close', 'escalation_decision', 'learning_extraction' )),
-- Busca semântica query_text TEXT, query_embedding vector(768), matched_doc_ids UUID[] DEFAULT '{}', top_similarity NUMERIC(4,3), confidence_tier TEXT CHECK (confidence_tier IN ('T1','T2','T3')),
-- Resposta gerada generated_response TEXT, model_used TEXT DEFAULT 'gemini-flash', prompt_tokens INTEGER, completion_tokens INTEGER,
-- Resultado outcome TEXT CHECK (outcome IN ( 'sent_autonomously', 'draft_shown', 'routed_to_human', 'customer_satisfied', 'customer_not_satisfied', 'timeout_closed', 'knowledge_extracted', 'knowledge_updated' )), outcome_csat SMALLINT,
created_at TIMESTAMPTZ NOT NULL DEFAULT NOW() );
CREATE INDEX idx_ai_interactions_ticket ON ticket_ai_interactions(ticket_id, created_at); CREATE INDEX idx_ai_interactions_type ON ticket_ai_interactions(interaction_type);

migration.sql:
ALTER TABLE support_tickets
  ADD COLUMN ai_confidence     NUMERIC(4,3),         -- confiança da última busca semântica
  ADD COLUMN ai_attempt_count  SMALLINT DEFAULT 0,   -- quantas vezes a IA tentou resolver
  ADD COLUMN ai_doc_used_id    UUID REFERENCES support_knowledge_docs(id),
  ADD COLUMN ai_handled        BOOLEAN NOT NULL DEFAULT FALSE,  -- TRUE = resolvido pela IA sem humano
  ADD COLUMN ai_draft_response TEXT;                 -- rascunho gerado para agente revisar (tier T2)

-- Adicionar novos status ao enum existente
ALTER TYPE ticket_status ADD VALUE IF NOT EXISTS 'ai_responding';
ALTER TYPE ticket_status ADD VALUE IF NOT EXISTS 'ai_resolved';
ALTER TYPE ticket_status ADD VALUE IF NOT EXISTS 'needs_human';
ALTER TYPE ticket_status ADD VALUE IF NOT EXISTS 'learning';

